css:
.snap-page { background: radial-gradient(circle, rgba(20,20,20,.075) 1.7px, transparent 2.2px) 0 0 / 40px 40px, radial-gradient(120% 80% at 50% 30%, #FFFFFF 0%, var(--ground) 62%); }
.snap-page.night { background: radial-gradient(circle, rgba(250,250,250,.07) 1.7px, transparent 2.2px) 0 0 / 40px 40px, radial-gradient(120% 80% at 50% 30%, var(--nightcard) 0%, var(--night) 62%); }
.snap-card { background: var(--card); border: 2px solid var(--border); border-radius: 28px; box-shadow: 0 2px 4px rgba(20,20,20,.04), 0 30px 70px rgba(20,20,20,.09); }
.night .snap-card { background: var(--nightcard); border-color: #26272B; box-shadow: none; }
.snap-chip { display: inline-flex; align-items: center; gap: 16px; padding: 14px 28px 14px 22px; border: 2px solid var(--border); border-radius: 999px; background: var(--card); font: 500 34px/1 var(--font-mono); color: var(--muted); letter-spacing: -0.01em; white-space: nowrap; }
.snap-chip i { width: 16px; height: 16px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 7px var(--ring); }
.night .snap-chip { background: var(--nightcard); border-color: #26272B; color: #A1A1AA; }
.snap-head { margin: 0; font: 600 112px/1.04 var(--font-display); letter-spacing: -0.035em; color: var(--ink); text-wrap: balance; }
.night .snap-head { color: #FAFAFA; }
.snap-head .w { display: inline-block; transform-origin: 50% 100%;}
.snap-head em { font-style: normal; color: var(--accent); }
.snap-sub { font: 500 44px/1.3 var(--font-body); letter-spacing: -0.015em; color: var(--muted); }
.snap-hl { padding: 0 0.06em; margin: 0 -0.06em; background: linear-gradient(var(--ring), var(--ring)) no-repeat 0 86% / 0% 0.36em; box-decoration-break: clone; -webkit-box-decoration-break: clone; }
.snap-whip { position: absolute; inset: 0; }
.snap-head.word { font-size: 236px; line-height: .9; letter-spacing: -0.055em; }
.snap-head .dot { display: inline-block; color: var(--accent); }
.snap-page.flip { background: radial-gradient(circle, color-mix(in srgb, var(--on-accent) 12%, transparent) 1.7px, transparent 2.2px) 0 0 / 40px 40px, var(--accent); }
.flip .snap-head, .flip .snap-head em, .flip .snap-head .dot { color: var(--on-accent); }
.flip .snap-hl { background-image: linear-gradient(color-mix(in srgb, var(--on-accent) 22%, transparent), color-mix(in srgb, var(--on-accent) 22%, transparent)); }
.flip .snap-chip { background: transparent; border-color: color-mix(in srgb, var(--on-accent) 40%, transparent); color: var(--on-accent); }
.flip .snap-chip i { background: var(--on-accent); box-shadow: none; }
